/** Put an order's lines back into the caller's cart, skipping products no longer sold. */
export function reorder(ctx: AppContext, user: User, id: string) {
  const order = getOrder(ctx, id);
  if (order.userId !== user.id) throw notFound('order');
  const added: { productId: string; quantity: number }[] = [];
  const skipped: string[] = [];
  for (const line of order.lines) {
    if (!ctx.store.products.require(line.productId).active) {
      skipped.push(line.productId);
      continue;
    }
    addItem(ctx, user.id, line.productId, line.quantity);
